import asyncio
import time

import pytest
import tomli_w
import tomllib

from boxyard._enums import BoxPart
from boxyard._sync_policy import check_record_path, read_check_record, write_check_record
from boxyard.cmds import modify_boxmeta, new_box
from boxyard.config import get_config


def _set_policies(config_path, policies):
    with open(config_path, "rb") as f:
        dump = tomllib.load(f)
    dump["sync_policies"] = policies
    config_path.write_text(tomli_w.dumps(dump))
    return get_config(config_path)


def _make_box(config_path, remote_name, name, groups):
    """Create a box on the test remote and put it in `groups`."""
    index_name = new_box(
        config_path=config_path,
        box_name=name,
        storage_location=remote_name,
        verbose=False,
        claim=False,
    )
    if groups:
        modify_boxmeta(
            config_path=config_path,
            box_index_name=index_name,
            modifications={"groups": list(groups)},
        )
    return index_name



def _run_multi_sync(config_path, *args):
    """
    Invoke `multi-sync` through the real CLI.

    Deliberately NOT a direct call to `cli_multi_sync`: typer only materialises
    an `Option(...)` default when it parses a command line, so a direct call
    leaves every unpassed option as an `OptionInfo` object -- which is truthy,
    so `--box`/`--storage-location` both look provided and the command refuses.
    Going through the runner also exercises the flag parsing itself, which is
    the part a user actually touches.
    """
    from typer.testing import CliRunner

    from boxyard._cli.app import app

    result = CliRunner().invoke(
        app, ["--config", str(config_path), "multi-sync", *args]
    )
    assert result.exit_code == 0, (
        f"multi-sync {args} exited {result.exit_code}\n{result.output}"
        + (f"\n{result.exception!r}" if result.exception else "")
    )
    return result


FLEET = {
    "default": {"data_interval": "6h", "meta_interval": "15m", "compress": False},
    "cold": {"data_interval": "7d", "compress": False, "groups": ["archived", "dormant"]},
}

