def test_a_yard_with_no_policies_syncs_everything(temp_boxyard):
    """
    The property that makes this shippable: a machine that has not opted in
    must behave EXACTLY as it does today. If this ever fails, four fifths of
    the fleet silently stops syncing.
    """
    from boxyard._sync_policy import due_boxes
    from boxyard._models import get_boxyard_meta

    remote_name, _, config, config_path, _ = temp_boxyard
    for i in range(3):
        _make_box(config_path, remote_name, f"box-{i}", [])

    config = get_config(config_path)
    assert config.sync_policies == {}, "fixture must start with no policies"

    metas = get_boxyard_meta(config).box_metas
    result = due_boxes(config, metas, BoxPart.DATA, time.time())
    assert len(result.due) == len(metas) == 3
    assert result.skipped == []

    # ...and again immediately. With no cadence there is nothing to wait for.
    assert len(due_boxes(config, metas, BoxPart.DATA, time.time()).due) == 3

