def test_due_only_narrows_to_the_boxes_whose_cadence_says_so(temp_boxyard):
    from boxyard._sync_policy import due_boxes
    from boxyard._models import get_boxyard_meta

    remote_name, _, config, config_path, _ = temp_boxyard
    _make_box(config_path, remote_name, "hot-box", [])
    _make_box(config_path, remote_name, "cold-box", ["archived"])
    config = _set_policies(config_path, FLEET)

    metas = get_boxyard_meta(config).box_metas
    now = time.time()

    # Both checked an hour ago: neither is due (6h and 7d).
    for meta in metas:
        write_check_record(config, meta.index_name, BoxPart.DATA, now - 3600)
    assert due_boxes(config, metas, BoxPart.DATA, now).due == []

    # Eight hours on, the 6h box is due and the 7d box is not.
    later = now + 8 * 3600
    due = due_boxes(config, metas, BoxPart.DATA, later).due
    assert [n for n in due if "hot-box" in n]
    assert not [n for n in due if "cold-box" in n]

    # Eight DAYS on, both are.
    much_later = now + 8 * 86400
    assert len(due_boxes(config, metas, BoxPart.DATA, much_later).due) == 2


def test_a_completed_sync_restarts_the_clock(temp_boxyard):
    """
    The wiring `_record_check` provides. Without it every box stays due
    forever and `--due-only` is a no-op that looks like it works.
    """
    from boxyard._models import get_boxyard_meta
    from boxyard._sync_policy import due_boxes

    remote_name, _, config, config_path, _ = temp_boxyard
    _make_box(config_path, remote_name, "a-box", [])
    config = _set_policies(config_path, FLEET)
    meta = get_boxyard_meta(config).box_metas[0]

    assert read_check_record(config, meta.index_name, BoxPart.DATA) is None

    _run_multi_sync(config_path, "--due-only")

    record = read_check_record(config, meta.index_name, BoxPart.DATA)
    assert record is not None, "a completed sync must record the check"
    assert abs(record["last_checked_unix"] - time.time()) < 60

    # Immediately after, the box is no longer due.
    metas = get_boxyard_meta(config).box_metas
    assert due_boxes(config, metas, BoxPart.DATA, time.time()).due == []


def test_an_explicit_box_beats_the_cadence(temp_boxyard):
    """
    Naming a box asks for THAT box. A cadence is a default for the unattended
    loop, never an override of a person's explicit instruction.
    """
    from boxyard._cli.multi_sync import cli_multi_sync
    from boxyard._models import get_boxyard_meta

    remote_name, _, config, config_path, _ = temp_boxyard
    _make_box(config_path, remote_name, "a-box", [])
    config = _set_policies(config_path, FLEET)
    meta = get_boxyard_meta(config).box_metas[0]

    # Mark it freshly checked, so a cadence-driven pass would skip it...
    write_check_record(config, meta.index_name, BoxPart.DATA, time.time())
    # ...and ask for it by name WITHOUT --due-only. It must still sync.
    _run_multi_sync(config_path, "--box", meta.index_name)
    assert read_check_record(config, meta.index_name, BoxPart.DATA) is not None


def test_a_failed_sync_does_not_restart_the_clock(temp_boxyard, monkeypatch):
    """
    An incomplete check must NOT record, or a box that fails every pass goes
    quiet for its whole interval instead of being retried.

    The failure is injected rather than contrived: `sync_box` is what raises in
    the real Error path, so making IT raise exercises the branch that matters.
    """
    import boxyard.cmds as cmds_module
    from boxyard._models import get_boxyard_meta

    remote_name, _, config, config_path, _ = temp_boxyard
    _make_box(config_path, remote_name, "doomed-box", [])
    config = _set_policies(config_path, FLEET)
    meta = get_boxyard_meta(config).box_metas[0]

    async def _explode(*args, **kwargs):
        raise RuntimeError("remote went away")

    # Patched at the SOURCE namespace: `multi_sync` does `from boxyard.cmds
    # import sync_box` inside the command body, so the name is resolved at call
    # time and patching the module it is imported FROM is what takes effect.
    monkeypatch.setattr(cmds_module, "sync_box", _explode)
    _run_multi_sync(config_path, "--due-only")

    assert read_check_record(config, meta.index_name, BoxPart.DATA) is None, (
        "a failed sync recorded a check -- the box would now go quiet for a "
        "full interval instead of being retried next pass"
    )


def test_a_meta_only_pass_records_the_meta_clock(temp_boxyard):
    """
    META and DATA keep separate clocks, so a `-c meta` pass must stamp META and
    leave DATA alone. This is what lets the fast META loop and the slow DATA
    loop coexist without either resetting the other's cadence.
    """
    from boxyard._models import get_boxyard_meta

    remote_name, _, config, config_path, _ = temp_boxyard
    _make_box(config_path, remote_name, "a-box", [])
    config = _set_policies(config_path, FLEET)
    meta = get_boxyard_meta(config).box_metas[0]

    _run_multi_sync(config_path, "-c", "meta")

    assert read_check_record(config, meta.index_name, BoxPart.META) is not None, (
        "a meta-only pass did not stamp the META clock"
    )
    assert read_check_record(config, meta.index_name, BoxPart.DATA) is None, (
        "a meta-only pass stamped the DATA clock, which would silently reset "
        "the slow cadence every time the fast loop ran"
    )


def test_due_only_actually_skips_a_box_that_is_not_due(temp_boxyard):
    """
    The load-bearing one. Everything else here would still pass if `--due-only`
    were a no-op: this asserts the box was NOT touched, by pinning the check
    record's timestamp to the value it was given rather than the time of the
    run.
    """
    from boxyard._models import get_boxyard_meta

    remote_name, _, config, config_path, _ = temp_boxyard
    _make_box(config_path, remote_name, "fresh-box", [])
    config = _set_policies(config_path, FLEET)
    meta = get_boxyard_meta(config).box_metas[0]

    stamped = time.time() - 60  # checked a minute ago; cadence is 6h
    write_check_record(config, meta.index_name, BoxPart.DATA, stamped)

    _run_multi_sync(config_path, "--due-only")

    record = read_check_record(config, meta.index_name, BoxPart.DATA)
    assert record["last_checked_unix"] == stamped, (
        "the box was re-synced despite not being due -- --due-only did not filter"
    )


def test_a_policy_conflict_is_reported_on_stderr(temp_boxyard):
    """
    A conflicted box syncs, but never silently. The message goes to stderr so
    an unattended loop's stdout stays parseable.
    """
    from boxyard._models import get_boxyard_meta

    remote_name, _, config, config_path, _ = temp_boxyard
    _make_box(config_path, remote_name, "torn-box", ["archived", "live"])
    _set_policies(
        config_path,
        {
            "default": {"data_interval": "6h"},
            "cold": {"data_interval": "7d", "groups": ["archived"]},
            "hot": {"data_interval": "1h", "groups": ["live"]},
        },
    )
    result = _run_multi_sync(config_path, "--due-only")
    assert "Sync policy conflict" in result.output
    assert "cold" in result.output and "hot" in result.output


def test_the_most_overdue_box_is_synced_first(temp_boxyard):
    """
    A machine that was off comes back with everything due at once, so the order
    is what decides which work happens before the pass is next interrupted.
    The line numbering `(n/N)` follows the order of the selected list, so it
    reports the schedule rather than the completion race.
    """
    from boxyard._models import get_boxyard_meta

    remote_name, _, config, config_path, _ = temp_boxyard
    for name in ("aaa-slightly", "bbb-most", "ccc-middling"):
        _make_box(config_path, remote_name, name, [])
    config = _set_policies(config_path, FLEET)

    now = time.time()
    ages = {"aaa-slightly": 7, "bbb-most": 300, "ccc-middling": 30}  # hours
    for meta in get_boxyard_meta(config).box_metas:
        for name, hours in ages.items():
            if meta.name == name:
                write_check_record(
                    config, meta.index_name, BoxPart.DATA, now - hours * 3600
                )

    result = _run_multi_sync(config_path, "--due-only")

    # Located by index name rather than by parsing the decorated line: the
    # pass output is rich-rendered and wraps, so a regex over it is brittle.
    positions = {}
    for meta in get_boxyard_meta(config).box_metas:
        at = result.output.find(meta.index_name)
        assert at != -1, f"{meta.index_name} missing from the pass output"
        positions[meta.name] = at

    # Alphabetical order would give aaa, bbb, ccc -- the names are chosen so a
    # registry-ordered pass and an overdue-ordered pass cannot look the same.
    assert (
        positions["bbb-most"] < positions["ccc-middling"] < positions["aaa-slightly"]
    ), positions
